// Reuse the independent original-group audit, including its lossless row,
// prior-admission, fallback and untouched-rejection assertions.
#define main generated_partial_matrix_audit_main
#include "tests/native/partial_matrix_group_host.cpp"
#undef main
#include <fstream>
#include <iostream>
#include <stdexcept>

std::vector<uint16_t> read(const char* path, size_t count) {
    std::ifstream f(path,std::ios::binary|std::ios::ate);
    if (!f || f.tellg()!=std::streamoff(count*2u)) throw std::runtime_error("capture extent");
    std::vector<uint16_t> x(count); f.seekg(0); f.read(reinterpret_cast<char*>(x.data()),count*2u);
    if (!f) throw std::runtime_error("capture read");
    return x;
}
int main(int argc,char** argv) try {
    if (argc!=4) throw std::runtime_error("Q K full8192");
    const unsigned tokens=std::stoul(argv[3]);
    if (tokens!=8192u && tokens!=8192u) throw std::runtime_error("shape");
    auto q=read(argv[1],8192u*4096u),k=read(argv[2],8192u*512u);
    for (auto pair : {std::make_pair(&q,4096u),std::make_pair(&k,512u)}) {
        const auto initial=*pair.first;
        pair.first->insert(pair.first->end(),initial.begin(),initial.begin()+size_t(tokens-8192u)*pair.second);
    }
    uint64_t valid_q=0u,valid_k=0u;
    for(unsigned side=0u;side<2u;++side){
        const auto& values=side?k:q;
        for(size_t row=0u;row<values.size()/256u;++row){
            bool good=true;for(unsigned i=0u;i<256u;++i)good&=qrt_sm121_narrow_f32_carry::eligible(values[row*256u+i]);
            (side?valid_k:valid_q)+=good;
        }
    }
    Counts count; uint64_t dots=0,eligible=0;
    for (unsigned sample=0;sample<128u;++sample) {
        const unsigned query=32u+sample*(tokens-33u)/127u;
        const unsigned prefix=(query/32u)*32u;
        for (unsigned head=0;head<16u;++head) for (unsigned key_sample=0;key_sample<32u;++key_sample) {
            const unsigned key=key_sample*prefix/32u;
            const uint16_t* a=q.data()+(size_t(query)*16u+head)*256u;
            const uint16_t* b=k.data()+(size_t(key)*2u+head/8u)*256u;
            bool narrow=true;
            for (unsigned i=0;i<256u;++i)
                narrow &= qrt_sm121_narrow_f32_carry::eligible(a[i]) && qrt_sm121_narrow_f32_carry::eligible(b[i]);
            ++dots; if (!narrow) continue; ++eligible;
            original::Value carry{0u,-133,false}; float carried=0.0f;
            for (unsigned g=0;g<16u;++g) carried=group(carried,carry,a+g*16u,b+g*16u,count);
        }
    }
    std::cout << "{\"kind\":\"captured_qk_partial_matrix_host_sample\",\"tokens\":" << tokens
        << ",\"source_capture_tokens\":8192,\"repeated_rows\":" << tokens-8192u
        << ",\"eligible_query_rows\":"<<valid_q<<",\"eligible_key_rows\":"<<valid_k
        << ",\"query_samples\":128,\"heads\":16,\"keys_per_query_head\":32,\"sampled_dots\":" << dots
        << ",\"domain_eligible_dots\":" << eligible << ",\"ordered_groups\":" << count.groups
        << ",\"original_matrix_admitted\":" << count.original_admitted
        << ",\"additional_remainder_admitted\":" << count.remainder_admitted
        << ",\"additional_partial_admitted\":" << count.partial_admitted
        << ",\"partial_scalar_products\":" << count.sparse_products
        << ",\"original_narrow_fallback\":" << count.rejected
        << ",\"lossless_prepared_words\":" << count.words
        << ",\"raw_carry_mismatches\":0,\"host_arithmetic_only\":true,\"gpu_executed\":false,\"inference_acceptance\":false}\n";
} catch (const std::exception& e) { std::cerr << e.what() << '\n'; return 2; }

