#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <vector>
#define __global__
struct Dim {unsigned x;};
Dim blockIdx{},threadIdx{},blockDim{256u};
using std::isfinite;
void atomicAdd(unsigned* p,unsigned v){*p+=v;}
uint16_t f32_to_bf16(float value){uint32_t b;std::memcpy(&b,&value,4);return uint16_t((b+0x7fffu+((b>>16)&1u))>>16);}
__global__ void external_source_context(const float* output,const uint16_t* reference,
    unsigned start,unsigned queries,unsigned source_tokens,unsigned* bad,unsigned* compared){
    const unsigned first=blockIdx.x*blockDim.x,index=first+threadIdx.x;
    const unsigned available=start<source_tokens?(source_tokens-start)*4096u:0u;
    const unsigned valid=available<queries*4096u?available:queries*4096u;
    if(!threadIdx.x&&first<valid)atomicAdd(compared,valid-first<blockDim.x?valid-first:blockDim.x);
    if(index<queries*4096u){
        const float value=output[index];
        if(!isfinite(value)||(index<valid&&f32_to_bf16(value)!=reference[size_t(start)*4096u+index]))
            atomicAdd(bad,1u);
    }
}

int main(){
 unsigned cases=0u;
 const unsigned shapes[][3]={{0,1,1},{0,2,1},{7168,2,7169},{7168,2,8192},{8190,2,8192},{8190,2,8191},{8190,2,7169},{8064,128,8192},{8064,128,7169}};
 for(const auto& s:shapes){
  const unsigned start=s[0],queries=s[1],source=s[2];
  const unsigned compared_rows=std::min(queries,start<source?source-start:0u);
  for(unsigned fault=0u;fault<4u;++fault){
   std::vector<uint16_t> reference(size_t(source)*4096u,0x3f80u);
   std::vector<float> output(size_t(queries)*4096u,1.0f);
   unsigned expected_bad=0u;
   if(fault==1u&&compared_rows){reference[(size_t(start)+compared_rows)*4096u-1u]=0x4000u;expected_bad=1u;}
   if(fault==2u){output.back()=std::numeric_limits<float>::infinity();expected_bad=1u;}
   if(fault==3u){output.back()=2.0f;expected_bad=compared_rows==queries?1u:0u;}
   const auto before_reference=reference;const auto before_output=output;
   unsigned bad=0u,compared=0u;
   for(blockIdx.x=0u;blockIdx.x<(queries*4096u+255u)/256u;++blockIdx.x)
    for(threadIdx.x=0u;threadIdx.x<256u;++threadIdx.x)
     external_source_context(output.data(),reference.data(),start,queries,source,&bad,&compared);
   if(bad!=expected_bad||compared!=compared_rows*4096u||reference!=before_reference||output!=before_output)throw std::runtime_error("reference extent or fault control");
   ++cases;
  }
 }
 std::cout<<"{\"cases\":"<<cases<<",\"final_original_row_fault_rejected\":true,\"short_reference_extent_preserved\":true,\"nonfinite_unreferenced_row_rejected\":true,\"inputs_unchanged\":true,\"host_coordinate_mock_only\":true,\"gpu_executed\":false}\n";
}
